head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.market = "";  // 시장
scwin.bondYn = "";  // 채권상장팀 여부

let regPw = ""; // 등록된 비밀번호
let pData = {}; // 부모화면에서 넘어온 데이터

const crudList = [
    {"gubun" : "02", "confirmMsgStr" : "입력", "successMsgStr" : "등록", "apiUrl" : "/api/discls/dsclinfo/insert-notice-content"}   // 02 : SCREN_PROCS_TP_CD_02
    , {"gubun" : "03", "confirmMsgStr" : "수정", "successMsgStr" : "수정", "apiUrl" : "/api/discls/dsclinfo/update-notice-content"}   // 03 : SCREN_PROCS_TP_CD_03
    , {"gubun" : "04", "confirmMsgStr" : "삭제", "successMsgStr" : "삭제", "apiUrl" : "/api/discls/dsclinfo/delete-notice-content"}   // 04 : SCREN_PROCS_TP_CD_04
    ];

let crudObj = {};       // 등록, 수정, 삭제 object
let delFileList = [];   // 삭제 할 파일 목록

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 부모화면 데이터(pData)를 수신해 컴포넌트를 초기화하고, 등록 모드면 등록자 정보를 세팅, 수정 모드면 공지사항 상세를 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        pData = $c.data.getParameter().pData; // 부모화면에서 넘어온 데이터
        scwin.market = $c.stf.getUserInfo("market");

        if($c.util.isEmpty(pData))    return;
        else
        {
            // 컴포넌트 초기화
            scwin.compInit();

            // 부모화면에서 가져온 regFlag가 true인경우 (= 입력 버튼  클릭)
            if(pData.regFlag)
            {
                // 시장구분 행 visible 세팅
                pnl_mkt_gubun.visible(scwin.market === "9");

                // 삭제버튼 visible false
                btn_delete.visible(false);

                // 채권공시관련
                scwin.bondYn = $c.stf.getUserInfo("bondYn");

                let mktNm = "";

                if(scwin.bondYn === "Y")    mktNm = "(채)";
                else if(scwin.market === "1") mktNm = "(유)";
                else if(scwin.market === "2") mktNm = "(코)";

                // 등록자 data setting
                dma_notice.set("wrtrEmpNm", mktNm + $c.stf.getUserInfo("depNm"));

            }else   // 수정버튼 클릭 시
            {
                // 공지사항 내용 조회
                $c.sbm.execute(sbm_getNoticeDetail, pData.row);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_cancel_onclick
 * @description 취소 버튼 이벤트 — 저장 없이 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cancel_onclick(e);
 */
scwin.btn_cancel_onclick = function (e) {
    try {
        $c.win.closePopup({"saveFlag": false});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name chk_notiObjSysCd_onviewchange
 * @description 공지대상시스템 checkbox 변경 이벤트 — 체크 여부·선택값에 따라 관련 영역을 세팅한다.
 * @param {Object} info 변경 정보 객체(checked: 체크 여부, value: 선택값)
 * @returns {void}
 * @hidden N
 * @example scwin.chk_notiObjSysCd_onviewchange(info);
 */
scwin.chk_notiObjSysCd_onviewchange = function (info) {
    try {
        const chk = info.checked;
        const val = info.value;

        scwin.notiObjSysTpCdChange(chk, val);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.chk_notiObjSysCd_onviewchange" });
    }
};

/**
 * @method
 * @name rdo_bbs_tp_cd_onviewchange
 * @description 공지구분 라디오버튼 클릭 이벤트 — 밸류업(60) 선택 시 시장구분을 전체(9)로 고정하고, 그 외에는 로그인 시장구분으로 세팅한다.
 * @param {Object} info 변경 정보 객체(value: 선택된 공지구분값)
 * @returns {void}
 * @hidden N
 * @example scwin.rdo_bbs_tp_cd_onviewchange(info);
 */
scwin.rdo_bbs_tp_cd_onviewchange = function (info) {
    try {
        const val = info.value;   // 선택값

        rdo_mkt_gubun.setDisabled(false);

        // 밸류업 인 경우
        if(val === "60")
        {
            dma_notice.set("mktTpCd", "9");
            rdo_mkt_gubun.setDisabled(true);
            pnl_mkt_gubun.visible(true);
        }else
        {
            if(pData.regFlag)
            {
                dma_notice.set("mktTpCd", scwin.market);

                if(scwin.market === "9")
                {
                    dma_notice.set("mktTpCd", "9");
                    pnl_mkt_gubun.visible(true);
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.rdo_bbs_tp_cd_onviewchange" });
    }
};

/**
 * @method
 * @name btn_fileAdd_onclick
 * @description 파일 추가 클릭 이벤트 — 첨부파일 최대 개수(5개)를 체크한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_fileAdd_onclick(e);
 */
scwin.btn_fileAdd_onclick = function (e) {
    try {
        const listCnt = dlt_fileList.getRowCount();

        if(listCnt === 5){
            $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }

        $c.win.alert("개발예정");
        return;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.btn_fileAdd_onclick" });
    }
};

/**
 * @method
 * @name btn_fileRemove_onclick
 * @description 파일 삭제 클릭 이벤트 — 체크된 파일을 삭제 목록에 담고 그리드에서 행을 삭제한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_fileRemove_onclick(e);
 */
scwin.btn_fileRemove_onclick = function (e) {
    try {
        // 초기화
        delFileList = [];

        // 삭제할 파일 list set
        delFileList = dlt_fileList.getMatchedJSON("chk", "T")

        // 그리드에서 행 삭제
        const chkIdxs = dlt_fileList.getMatchedIndex("chk", "T");
        dlt_fileList.removeRows(chkIdxs);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.btn_fileRemove_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 저장 버튼 클릭 이벤트 — 등록(02)/수정(03) 구분으로 유효성 체크 후 저장을 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_save_onclick(e);
 */
scwin.btn_save_onclick = function (e) {
    try {
        scwin.valid(pData.regFlag? "02" : "03");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제버튼 이벤트 함수 — 삭제(04) 구분으로 유효성 체크 후 삭제를 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_delete_onclick(e);
 */
scwin.btn_delete_onclick = function (e) {
    try {
        scwin.valid("04");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name mcu_file_ondone
 * @description 파일업로드 컴포넌트 ondone 이벤트 — 업로드 결과 데이터를 로깅한다.
 * @param {Object} data 업로드 결과 데이터
 * @returns {void}
 * @hidden N
 * @example scwin.mcu_file_ondone(data);
 */
scwin.mcu_file_ondone = function (data) {
    try {
        console.log("mcu_file_ondone::data:",data);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.mcu_file_ondone" });
    }
};

/**
 * @method
 * @name mcu_file_oncomplete
 * @description 파일업로드 컴포넌트 oncomplete 이벤트 — 업로드 완료를 로깅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.mcu_file_oncomplete();
 */
scwin.mcu_file_oncomplete = function () {
    try {
        console.log("mcu_file_onComplete");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.mcu_file_oncomplete" });
    }
};

/**
 * @method
 * @name grd_fileList_oncellclick
 * @description 파일목록 그리드 oncell click 이벤트 — 첨부파일명 클릭 시 파일을 다운로드한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_fileList_oncellclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_fileList_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        const fileData = dlt_fileList.getRowJSON(rowIndex);
        const contnId = dma_notice.get("contnId");

        if(columnId === "attachFileNm"){
            let url = "/api/discls/common/file/download";
            url += "?gubun=2&contnId=" + contnId + "&contnAttachSeq=" + fileData.contnAttachSeq;

            $p.download(url, {}, "get", true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30401.grd_fileList_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_getNoticeDetail_submitdone
 * @description 공지사항 상세조회 submission 결과 — 상세 데이터를 dma_notice·파일목록에 세팅하고 공지대상시스템·비밀번호 표시 상태를 초기화한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_getNoticeDetail_submitdone(e);
 */
scwin.sbm_getNoticeDetail_submitdone = function (e) {
    regPw = "";

    if(e.responseJSON.success)
    {
        const mergeData = {...pData.row, ...e.responseJSON.body};

        // dma_notice set
        dma_notice.setJSON(mergeData);

        // dma_fileList set
        dlt_fileList.setJSON(mergeData?.attachFileInfoList?? []);

        // 공지대상시스템 checkbox click
        scwin.notiObjSysTpCdChange(true, dma_notice.get("notiObjSysTpCd"));

        // 공지대상 inputbox show, 공지대상시스템 체크박스 hide
        ibx_notiObjSysCd.removeClass("hide");
        chk_notiObjSysCd.addClass("hide");

        // 비밀번호 초기화
        regPw = dma_notice.get("pw");
        dma_notice.set("pw", "");

    }
};

/**
 * @method
 * @name sbm_transNotice_submitdone
 * @description 등록, 수정, 삭제 submission 결과 — 처리 결과 메시지를 띄우고 성공 시 팝업을 닫는다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_transNotice_submitdone(e);
 */
scwin.sbm_transNotice_submitdone = function (e) {

    const msgCd = (e.responseJSON.success)? "MSG-A001" : "MSG-A002";

    $c.win.alert($c.stf.getMessageParam(msgCd, "공지사항" + crudObj.successMsgStr), () => {
        if(e.responseJSON.success)  $c.win.closePopup({"saveFlag": true});
        return;
    });
};

/**
 * @method
 * @name selectCallback
 * @description 파일업로드시 파일정보 dataList에 세팅 — 선택한 파일 정보(파일명·크기)를 dlt_fileList 에 추가한다.
 * @returns {void}
 * @hidden N
 * @example scwin.selectCallback();
 */
scwin.selectCallback = function() {
    const fileInfos = mcu_file.getFileInfos();

    const fileList = fileInfos.map(({name, size, ...f}) => ({
        ...f
        , "attachFileNm" : name
        , "attachFileSz" : size
    }));

    dlt_fileList.setJSON(fileList, true);
}

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name compInit
 * @description 컴포넌트 초기화 — 공지대상시스템 inputbox·시장구분·공지구분·담당기관 영역의 초기 표시 상태와 데이터를 세팅한다.
 * @returns {void}
 * @hidden N
 * @example scwin.compInit();
 */
scwin.compInit = function() {

    // 공지대상시스템 inputbox hide
    if(!ibx_notiObjSysCd.hasClass("hide"))  ibx_notiObjSysCd.addClass(hide);

    // 시장구분
    if(scwin.market === "9")    pnl_mkt_gubun.visible(false);
    dma_notice.set("mktTpCd", scwin.market); // data setting

    // 공지구분
    pnl_valueup.visible(false);
    dma_notice.set("bbsTpCd", "03");

    // 담당기관 visible
    pnl_kclic.visible(false);

}

/**
 * @method
 * @name mktGubunVisible
 * @description 시장구분값 visible — 로그인 시장구분이 전체(9)인 경우 시장구분 영역의 표시 여부를 전환한다.
 * @param {Boolean} flag 표시 여부
 * @returns {void}
 * @hidden N
 * @example scwin.mktGubunVisible(true);
 */
scwin.mktGubunVisible = function(flag) {
    if(scwin.market === "9")    pnl_mkt_gubun.visible(flag);
}

/**
 * @method
 * @name notiObjSysTpCdChange
 * @description 공지대상시스템 checkbox 함수 — 선택값별로 공지구분·시장구분·담당기관 영역 표시와 체크박스 사용 여부를 세팅한다.
 * @param {Boolean} chkFlag 체크 여부
 * @param {String} val 공지대상시스템 코드값
 * @returns {void}
 * @hidden N
 * @example scwin.notiObjSysTpCdChange(true, "2");
 */
scwin.notiObjSysTpCdChange = function(chkFlag, val){

    switch (val)
    {
        case "2":   // 조회(국문)
            pnl_valueup.visible(chkFlag);          // 공지구분 tr
            break;

        case "D":   // 조회(영문)
            pnl_valueup.visible(chkFlag);       // 공지구분 tr
            rdo_bbs_tp_cd.setValue("60");   // 공지구분값 세팅

            const chkArr = chk_notiObjSysCd.getValue(",").split(",");    // checked data
            const rslt = chkArr.includes(val);

            if(chkArr.length > 1 && rslt){
                $c.win.alert("조회(영문)시스템은 다른 시스템과 같이 사용할 수 없습니다.", () => {
                    chk_notiObjSysCd.setValue(val); // 다른 체크박스는 체크 해제
                });
            }

            const allData = dlt_notiObjSysCd.getAllJSON();

            allData.forEach((item, idx) => {
                // unchecked 되면 다른 항목들도 enable
                chk_notiObjSysCd.setItemDisabled(idx, chkFlag? (item.code !== val) : chkFlag);
            });

            break;

        case "3": case "1": // 처리시스템, 제출(국문)
            scwin.mktGubunVisible(chkFlag);
            break;

        case "B": // K-CLIC
            scwin.mktGubunVisible(chkFlag);
            pnl_kclic.visible(chkFlag);    // 담당기관

            break;
        default:
            break;
    }

}

/**
 * @method
 * @name valid
 * @description 저장, 삭제 시 유효성 체크 — 필수값·이메일·비밀번호 등을 검증하고 확인 후 등록/수정/삭제 submission 또는 파일 업로드를 수행한다.
 * @param {String} val 처리구분코드(02:등록, 03:수정, 04:삭제)
 * @returns {void}
 * @hidden N
 * @example scwin.valid("02");
 */
scwin.valid = function(val) {

    crudObj = crudList.find(item => item.gubun === val);

    const valInfo = [
        { id: "notiObjSysTpCd", mandatory: pData.regFlag }               // 공지대상시스템코드
        , { id: "wrtrEmail", mandatory: true, isEmail : true }  // 이메일
        , { id: "pw", mandatory: pData.regFlag }                         // 비밀번호
        , { id: "notiStrtDd", mandatory: true }                 // 게시물적용시작일
        , { id: "title", mandatory: true }                      // 제목
        , { id: "contnMaindocContn", mandatory: true }          // 내용
    ];

    if ($c.data.validateGroup(grp_table, valInfo))
    {
        let valid = true;

        // 등록인 경우
        if(crudObj.gubun === "02")
        {
            const notiObjSysCd = dma_notice.get("notiObjSysTpCd");

            // 공지대상시스템 체크값에 K-CLIC값(=B) 이 있으면
            if(notiObjSysCd.includes("B"))
            {
                if($c.util.isEmpty(dma_notice.get("chrgInstId")))
                {
                    $c.win.alert("[공지대상 시스템]이 K-CLIC 일경우 담당기관을 선택해주세요.", () => {cmb_chrg_inst.focus();});
                    valid = false;
                    return;
                }
            }

            // 공지대상시스템 체크값이 조회(국문)(=2) 이고, 공지구분값이 밸류업(=60) 인 경우
            if(notiObjSysCd.includes("2") && dma_notice.get("bbsTpCd") === "60")
            {
                if(notiObjSysCd.length > 1)
                {
                    $c.win.alert("[공지대상 시스템]이 조회(국문)이면서 밸류업일 경우 다른 시스템과 함께 사용할 수 없습니다. ", () => {chk_notiObjSysCd.focus(); });
                    valid = false;
                    return;
                }
            }
        }else   // 수정 or 삭제인 경우
        {
            if(dma_notice.get("pw") !== regPw)
            {
                $c.win.alert("[비밀번호]를 잘못 입력하셨습니다.", () => {tbox_password.focus();});
                valid = false;
                return;
            }
        }

        if(valid)
        {
            $c.win.confirm("위사항을 "+ crudObj.confirmMsgStr +" 하시겠습니까?", (res) => {
                if (res.clickValue)
                {
                    // 조회(영문)일 , 밸류업일 경우 bbs_tp_cd = 61 이다
                    if(dma_notice.get("notiObjSysTpCd") === "D")    dma_notice.set("bbsTpCd", "61");

                    // 적용 끝일자가 없으면 자동으로 99991231 입력한다.
                    if($c.util.isEmpty(dma_notice.get("notiEndDd")))    dma_notice.set("notiEndDd", "99991231");

                    // 삭제인 경우 submission
                    if(crudObj.gubun === "04")
                    {
                        $c.sbm.setAction(sbm_transNotice, crudObj.apiUrl);
                        $c.sbm.execute(sbm_transNotice, dma_notice.getJSON());

                    }else   // 등록, 수정은 startUpload
                    {
                        const paramData = dma_notice.getJSON();
                        paramData.deleteFiles = delFileList;    // 수정용 삭제파일list 추가

                        mcu_file.changeAction(crudObj.apiUrl);
                        mcu_file.setParam(0, "data", JSON.stringify(paramData));

                        mcu_file.startUpload();

                    }
                }
            });
        }
    }
}
